using System;using System.Linq;using System.Collections.Generic;using TxTools.ExportByColor;
class AdaptiveCylinderDensityRegression{
 static void Check(bool b,string message){if(!b)throw new Exception(message);}
 static Dictionary<string,int> Edges(RoundHoleCgrMesh.Result r){var result=new Dictionary<string,int>();Func<int,string> key=id=>string.Join(",",r.Vertices[id].Select(v=>v.ToString("R",System.Globalization.CultureInfo.InvariantCulture)));foreach(var f in r.Faces)for(int k=0;k<3;k++){string a=key(f.Idx[k]),b=key(f.Idx[(k+1)%3]),edge=string.CompareOrdinal(a,b)<0?a+"|"+b:b+"|"+a;int n;result.TryGetValue(edge,out n);result[edge]=n+1;}return result;}
 static int Main(){try{foreach(int n in new[]{8,16,32})Run(n);return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static void Run(int n){var vs=new List<float[]>();for(int ring=0;ring<4;ring++)for(int i=0;i<n;i++){double a=2*Math.PI*i/n,r=ring<2?15:5,z=(ring==1||ring==3)?10:0;vs.Add(new[]{(float)(r*Math.Cos(a)),(float)(r*Math.Sin(a)),(float)z});}var fs=new List<CgrWriter.Face>();Action<int,int,int> add=(a,b,c)=>fs.Add(new CgrWriter.Face{Idx=new[]{a,b,c},Surface=1,R=15,G=20,B=25,Opacity=127});for(int i=0;i<n;i++){int j=(i+1)%n;add(i,j,n+j);add(i,n+j,n+i);add(2*n+i,3*n+j,2*n+j);add(2*n+i,3*n+i,3*n+j);add(i,2*n+j,j);add(i,2*n+i,2*n+j);add(n+i,n+j,3*n+j);add(n+i,3*n+j,3*n+i);}var snapshot=vs.Select(v=>(float[])v.Clone()).ToArray();var ids=fs.Select(f=>(int[])f.Idx.Clone()).ToArray();var holes=RoundHoleReconstruction.Find(vs,fs,new RoundHoleReconstruction.Options{IncludeExternalCylinders=true});var balanced=RoundHoleCgrMesh.Replace(vs,fs,holes);var fine=RoundHoleCgrMesh.Replace(vs,fs,holes,null,RoundHoleCgrMesh.DisplayOptions.Fine());Check(balanced.Cylinders.Count==2&&fine.Cylinders.Count==2,"Lost inner/outer measurement groups");Check(balanced.Faces.Count<fine.Faces.Count,"Adaptive profile did not reduce triangles");Check(Edges(balanced).Values.All(v=>v==2)&&Edges(fine).Values.All(v=>v==2),"Open/duplicate cap joins");foreach(var c in balanced.Cylinders.Values){var old=fine.Cylinders.Values.Single(o=>o.ExternalCylinder==c.ExternalCylinder);Check(c.Center.SequenceEqual(old.Center)&&c.Axis.SequenceEqual(old.Axis)&&c.Radius==old.Radius&&c.Depth==old.Depth,"Measurement parameters changed with density");foreach(var f in balanced.Faces.Where(f=>f.Surface==c.Surface))for(int k=0;k<3;k++){var a=balanced.Vertices[f.Idx[k]];var b=balanced.Vertices[f.Idx[(k+1)%3]];double radius=Math.Sqrt(Math.Pow(((double)a[0]+b[0])/2,2)+Math.Pow(((double)a[1]+b[1])/2,2));Check(c.Radius-radius<=.0201,"Balanced chord exceeds display target");}}Check(balanced.Faces.All(f=>f.R==15&&f.G==20&&f.B==25&&f.Opacity==127),"Material changed");Check(vs.Select((v,i)=>v.SequenceEqual(snapshot[i])).All(v=>v)&&fs.Select((f,i)=>f.Idx.SequenceEqual(ids[i])).All(v=>v),"Source mutated");Console.WriteLine("PASS adaptive density sourceSegments="+n+" triangles="+fine.Faces.Count+"->"+balanced.Faces.Count+"; identical cylinder parameters, 0.02mm sag, closed topology, RGBA and immutable source; no CGR readback");}
}
